\'../value_objects.dart\';\n\nclass UrlVO implements ValueObject<String> {\n  final String _value;\n  final String? _error;\n\n  UrlVO._(this._value, this._error);\n\n  factory UrlVO.create(String input) {\n    final trimmedInput = input.trim();\n    \n    // Validation\n    if (trimmedInput.isEmpty) {\n      return UrlVO._(trimmedInput, \'L\\\'URL est obligatoire\');\n    }\n\n    // Pattern pour validation d\'URL WordPress\n    final urlPattern = RegExp(\n      r\'^(https?:\/\/)?\' // http:// or https://\n      r\'(([a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,})\' // domaine\n      r\'(:[0-9]+)?\' // port optionnel\n      r\'(\\/.*)?$\', // chemin optionnel\n    );\n\n    if (!urlPattern.hasMatch(trimmedInput)) {\n      return UrlVO._(trimmedInput, \'URL invalide\');\n    }\n\n    // Normaliser l\'URL (ajouter https:// si manquant)\n    String normalizedUrl = trimmedInput;\n    if (!normalizedUrl.startsWith(\'http://\') && !normalizedUrl.startsWith(\'https://\')) {\n      normalizedUrl = \'https://$normalizedUrl\';\n    }\n\n    // Validation spécifique WordPress\n    if (!_isValidWordPressUrl(normalizedUrl)) {\n      return UrlVO._(normalizedUrl, \'URL WordPress invalide\');\n    }\n\n    return UrlVO._(normalizedUrl, null);\n  }\n\n  static bool _isValidWordPressUrl(String url) {\n    // Vérifications supplémentaires pour WordPress\n    try {\n      final uri = Uri.parse(url);\n      \n      // Éviter les URLs localhost en production\n      if (uri.host.contains(\'localhost\') || uri.host.contains(\'127.0.0.1\')) {\n        return false;\n      }\n\n      // Vérifier la longueur\n      if (url.length > 255) {\n        return false;\n      }\n\n      return true;\n    } catch (e) {\n      return false;\n    }\n  }\n\n  @override\n  String get value => _value;\n\n  @override\n  String? get error => _error;\n\n  @override\n  bool get isValid => _error == null;\n\n  @override\n  String toString() => _value;\n\n  // Méthodes utilitaires\n  String get domain {\n    try {\n      final uri = Uri.parse(_value);\n      return uri.host;\n    } catch (e) {\n      return _value;\n    }\n  }\n\n  String get cleanUrl {\n    return _value.replaceAll(RegExp(r\'https?://\'), \'\');\n  }\n\n  @override\n  bool operator ==(Object other) {\n    return identical(this, other) ||\n        (other is UrlVO &&\n            runtimeType == other.runtimeType &&\n            _value == other._value);\n  }\n\n  @override\n  int get hashCode => _value.hashCode;\n}\n